'use client';

import * as React from 'react';
import { flushSync } from 'react-dom';
import { SizeReadout } from '../size-readout/size-readout';
import './selection-frame.css';

/* ─────────────────────────────────────────────────────────
 * SELECTION FRAME · KAMUI-14 (the demo's renderSelection, as one object)
 *
 * rest      nothing: a borderless object has no edge at rest
 * hover     faint corner dots where the handles will be (settle fade);
 *           an edge light on the side the pointer entered the band
 * selected  ring 1.25 + collar 3.5 at offset 6 (radius + 6)
 *     0ms   ring and handles enter from 1.02, opacity 0, on the part spring
 *           (Reduce Motion: part resolves instant)
 *           the readout reads the measured frame: ● W × H
 *   typing  ring, handles and readout re-measure in the same frame as the
 *           host's layout (ResizeObserver runs before paint); the entrance
 *           never replays; the readout sits at .78
 *   moving  the readout returns to 1
 *   copied  the readout reads COPIED · PNG W × H for 900 ms
 * lite      one quiet 1 pt ring, no collar, no handles, no entrance: a
 *           member of a multi-selection, or a selection made by finishing
 * ───────────────────────────────────────────────────────── */

export type SelectionHandle = 'nw' | 'n' | 'ne' | 'e' | 'se' | 's' | 'sw' | 'w';
export type SelectionEdge = 'n' | 'e' | 's' | 'w';

export interface SelectionFrameProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** rest (nothing), hover (corner dots) or selected (ring, handles, readout). */
  state?: 'rest' | 'hover' | 'selected';
  /** ring: the one selection. lite: a quiet ring (multi-selection member, or a selection made by finishing). */
  variant?: 'ring' | 'lite';
  /** writing dims the readout to .78; moving returns it to 1. */
  mode?: 'idle' | 'writing' | 'moving';
  /** The object's corner radius. The ring's is this plus the selection offset (6). */
  radius?: number;
  /**
   * Which handles show. object: eight, all resize. text: corners and e/w set the width, n and s are
   * grips that move the object. none: no handles.
   */
  handles?: 'object' | 'text' | 'none';
  /** Show the readout under the object (default true while selected). */
  readout?: boolean;
  /** Blocks in a multi-selection: the readout reads "● N · W × H". */
  count?: number;
  /** The frame to read. Default: the host's measured border box, fractional, rounded for display. */
  size?: { width: number; height: number };
  /** Set to a format (e.g. "PNG") after a copy: the readout says so for 900 ms. */
  copied?: string | null;
  /** The band edge under the pointer: its edge light shows. */
  edge?: SelectionEdge | null;
  /** Play the ring's entrance when it becomes selected (default true). */
  entrance?: boolean;
  /** A handle was pressed. The host resizes or moves the object; the frame follows its box. */
  onHandlePointerDown?: (handle: SelectionHandle, event: React.PointerEvent<HTMLSpanElement>) => void;
}

const HANDLES: SelectionHandle[] = ['nw', 'n', 'ne', 'e', 'se', 's', 'sw', 'w'];
// Handle centres on the ring line, as fractions of the host box plus the offset outward.
const AT: Record<SelectionHandle, [number, number, number, number]> = {
  nw: [0, 0, -1, -1], n: [0.5, 0, 0, -1], ne: [1, 0, 1, -1], e: [1, 0.5, 1, 0],
  se: [1, 1, 1, 1], s: [0.5, 1, 0, 1], sw: [0, 1, -1, 1], w: [0, 0.5, -1, 0],
};
const place = (h: SelectionHandle): React.CSSProperties => {
  const [fx, fy, ox, oy] = AT[h];
  return { left: `calc(${fx * 100}% + var(--o) * ${ox})`, top: `calc(${fy * 100}% + var(--o) * ${oy})` };
};

/**
 * The host's border box, fractional and untransformed (a lifted or zoomed host reads its layout size),
 * re-read in the same frame as the host's layout: ResizeObserver runs after layout and before paint,
 * and flushSync commits the new numbers before that paint.
 */
function useHostSize(ref: React.RefObject<HTMLDivElement | null>, enabled: boolean) {
  const [size, setSize] = React.useState<{ width: number; height: number } | null>(null);
  React.useLayoutEffect(() => {
    const host = ref.current?.parentElement;
    if (!host || !enabled) return;
    const same = (a: { width: number; height: number } | null, w: number, h: number) => !!a && a.width === w && a.height === h;
    setSize((s) => (same(s, host.offsetWidth, host.offsetHeight) ? s : { width: host.offsetWidth, height: host.offsetHeight }));
    const ro = new ResizeObserver(([entry]) => {
      const b = entry.borderBoxSize?.[0];
      const w = b ? b.inlineSize : host.offsetWidth, h = b ? b.blockSize : host.offsetHeight;
      flushSync(() => setSize((s) => (same(s, w, h) ? s : { width: w, height: h })));
    });
    ro.observe(host, { box: 'border-box' });
    return () => ro.disconnect();
  }, [ref, enabled]);
  return size;
}

/**
 * KAMUI-14: the one selection for every kind of object. Place it as the last child of the object
 * (position: relative). For a borderless object the ring and its handles are the boundary.
 */
export const SelectionFrame = React.forwardRef<HTMLDivElement, SelectionFrameProps>(function SelectionFrame(
  {
    state = 'rest', variant = 'ring', mode = 'idle', radius = 0, handles = 'object', readout = true, count, size,
    copied, edge = null, entrance = true, onHandlePointerDown, className, style, ...props
  },
  forwardedRef,
) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(forwardedRef, () => ref.current as HTMLDivElement);
  const selected = state === 'selected';
  const measured = useHostSize(ref, selected && readout && !size);
  const box = size ?? measured;
  const showHandles = selected && variant === 'ring' && handles !== 'none';

  // "COPIED" holds for the token's 900 ms, then the readout reads the frame again.
  const [copiedShown, setCopiedShown] = React.useState<string | null>(null);
  React.useEffect(() => {
    if (!copied) return;
    setCopiedShown(copied);
    const ms = parseFloat(getComputedStyle(ref.current ?? document.documentElement).getPropertyValue('--mu-presence-copied-ms')) || 900;
    const t = setTimeout(() => setCopiedShown(null), ms);
    return () => clearTimeout(t);
  }, [copied]);

  return (
    <div
      ref={ref}
      aria-hidden
      data-state={state}
      data-variant={variant}
      data-mode={mode}
      data-entrance={entrance ? '' : undefined}
      className={className ? `mu-selection-frame ${className}` : 'mu-selection-frame'}
      style={{ '--mu-sf-radius': `${radius}px`, ...style } as React.CSSProperties}
      {...props}
    >
      <span className="mu-sf-ring" />
      {state === 'hover' || state === 'rest'
        ? (['nw', 'ne', 'se', 'sw'] as SelectionHandle[]).map((c) => <span key={c} className="mu-sf-dot" style={place(c)} />)
        : null}
      {(['n', 'e', 's', 'w'] as SelectionEdge[]).map((e) => (
        <span key={e} className="mu-sf-edge" data-edge={e} data-on={edge === e && state !== 'selected' ? '' : undefined} />
      ))}
      {showHandles &&
        HANDLES.map((k) => {
          const grip = handles === 'text' && (k === 'n' || k === 's');
          return (
            <span
              key={k}
              className="mu-sf-handle"
              data-handle={k}
              data-grip={grip ? '' : undefined}
              title={grip ? 'Drag to move' : handles === 'text' ? 'Drag to set the width · double-click to fit the text' : undefined}
              style={place(k)}
              onPointerDown={onHandlePointerDown ? (e) => onHandlePointerDown(k, e) : undefined}
            />
          );
        })}
      {selected && readout && box && <SizeReadout width={box.width} height={box.height} count={count} copied={copiedShown} />}
    </div>
  );
});

@import "../tokens.css";
@import "../size-readout/size-readout.css";

/* Selection frame (the reference design's .selring, .nub and .readout). Every value is a --mu-presence-* token (tokens.json presence).
   The frame is an overlay laid over its host: the host is position: relative, the frame fills it,
   and every part is placed from the host's box, so the ring tracks the object in the same frame. */
.mu-selection-frame {
  --o: var(--mu-select-offset);
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
}

/* ---- ring: 1.25 green at offset 6, a flat 3.5 collar outside it, never a blur ---- */
.mu-selection-frame > .mu-sf-ring {
  position: absolute;
  inset: calc(var(--o) * -1);
  border-radius: calc(var(--mu-sf-radius, var(--mu-zero)) + var(--o));
  opacity: 0;
  box-shadow:
    var(--mu-zero) var(--mu-zero) var(--mu-zero) var(--mu-presence-ring-width) var(--mu-presence-ring),
    var(--mu-zero) var(--mu-zero) var(--mu-zero) calc(var(--mu-presence-ring-width) + var(--mu-presence-collar-width)) var(--mu-presence-collar);
}
.mu-selection-frame[data-state="selected"] > .mu-sf-ring { opacity: 1; }
/* Entrance: 1.02 → 1 on the part spring, once; resizing never replays it. */
.mu-selection-frame[data-state="selected"][data-variant="ring"][data-entrance] > .mu-sf-ring {
  animation: mu-sf-in var(--mu-spring-part-d) var(--mu-spring-part) both;
}
@keyframes mu-sf-in {
  from { opacity: 0; transform: scale(var(--mu-presence-enter-scale)); }
}
/* Lite: a quiet ring for a multi-selection member or a selection made by finishing. */
.mu-selection-frame[data-variant="lite"] > .mu-sf-ring {
  box-shadow: var(--mu-zero) var(--mu-zero) var(--mu-zero) var(--mu-presence-lite-width) var(--mu-presence-lite);
}

/* ---- handles: on the ring line; round caps at corners, capsules at edge midpoints ---- */
.mu-sf-handle {
  position: absolute;
  width: var(--mu-presence-handle);
  height: var(--mu-presence-handle);
  translate: -50% -50%;
  border-radius: var(--mu-radius-pill);
  background: var(--mu-presence-handle-bg);
  box-shadow: var(--mu-presence-handle-sh);
  pointer-events: auto;
  touch-action: none;
}
.mu-sf-handle::after { content: ""; position: absolute; inset: calc(var(--mu-presence-handle-hit) * -1); border-radius: var(--mu-radius-pill); }
.mu-sf-handle[data-handle="e"], .mu-sf-handle[data-handle="w"] {
  width: var(--mu-presence-capsule-thickness);
  height: var(--mu-presence-capsule-length);
}
.mu-sf-handle[data-handle="n"], .mu-sf-handle[data-handle="s"] {
  width: var(--mu-presence-capsule-length);
  height: var(--mu-presence-capsule-thickness);
}
.mu-sf-handle[data-grip] { background: var(--mu-presence-grip-bg); box-shadow: var(--mu-presence-grip-sh); cursor: grab; }
.mu-sf-handle[data-handle="nw"], .mu-sf-handle[data-handle="se"] { cursor: nwse-resize; }
.mu-sf-handle[data-handle="ne"], .mu-sf-handle[data-handle="sw"] { cursor: nesw-resize; }
.mu-sf-handle[data-handle="e"], .mu-sf-handle[data-handle="w"] { cursor: ew-resize; }
.mu-sf-handle[data-handle="n"]:not([data-grip]), .mu-sf-handle[data-handle="s"]:not([data-grip]) { cursor: ns-resize; }
.mu-selection-frame[data-state="selected"][data-variant="ring"][data-entrance] .mu-sf-handle {
  animation: mu-sf-fade var(--mu-spring-part-d) var(--mu-spring-part) both;
}
@keyframes mu-sf-fade { from { opacity: 0; } }

/* ---- hover: only the faint corner dots, where the handles will be ---- */
.mu-sf-dot {
  position: absolute;
  width: var(--mu-presence-hover-dot);
  height: var(--mu-presence-hover-dot);
  translate: -50% -50%;
  border-radius: var(--mu-round);
  background: var(--mu-presence-dot);
  opacity: 0;
  transition: opacity var(--mu-spring-settle-d) var(--mu-spring-settle);
}
.mu-selection-frame[data-state="hover"] .mu-sf-dot { opacity: 1; }

/* ---- edge light: the pointer entered the band on one edge ---- */
.mu-sf-edge {
  position: absolute;
  opacity: 0;
  transition: opacity var(--mu-spring-settle-d) var(--mu-spring-settle);
}
.mu-sf-edge[data-on] { opacity: 1; }
.mu-sf-edge[data-edge="n"], .mu-sf-edge[data-edge="s"] {
  left: 0; right: 0; height: var(--mu-presence-edge-light-width);
  background: linear-gradient(90deg, transparent, var(--mu-presence-edge-light) 22%, var(--mu-presence-edge-light) 78%, transparent);
}
.mu-sf-edge[data-edge="n"] { top: calc(var(--mu-presence-edge-light-width) / -2); }
.mu-sf-edge[data-edge="s"] { bottom: calc(var(--mu-presence-edge-light-width) / -2); }
.mu-sf-edge[data-edge="e"], .mu-sf-edge[data-edge="w"] {
  top: 0; bottom: 0; width: var(--mu-presence-edge-light-width);
  background: linear-gradient(180deg, transparent, var(--mu-presence-edge-light) 22%, var(--mu-presence-edge-light) 78%, transparent);
}
.mu-sf-edge[data-edge="e"] { right: calc(var(--mu-presence-edge-light-width) / -2); }
.mu-sf-edge[data-edge="w"] { left: calc(var(--mu-presence-edge-light-width) / -2); }

/* The readout sits 16 under the object, centred. */
.mu-selection-frame > .mu-readout { position: absolute; left: 50%; top: calc(100% + var(--mu-presence-readout-gap)); transform: translateX(-50%); }
.mu-selection-frame[data-mode="writing"] .mu-readout { opacity: var(--mu-presence-readout-writing); }
.mu-selection-frame[data-mode="moving"] .mu-readout { opacity: 1; }

@media (prefers-contrast: more) {
  .mu-selection-frame[data-variant="lite"] > .mu-sf-ring { box-shadow: var(--mu-zero) var(--mu-zero) var(--mu-zero) var(--mu-presence-ring-width) var(--mu-presence-ring); }
}
